"""Opaque block identity preserves caller contract without allowing donation."""
from copy import deepcopy
from pathlib import Path

import pytest

from company_wiki.document_understanding import narrative_continuity as owner

assert Path(owner.__file__).resolve() == Path('C:/Users/郑曾波/Projects/company-wiki/tmp/w23-r6/src/company_wiki/document_understanding/narrative_continuity.py').resolve()


def pair(token):
    left={'unit_id':'l','kind':'paragraph','role':'company_filing','ordinal':0,'page':1,
          'text':'第一原始段','hints':{'source_id':'s'}}
    right={'unit_id':'r','kind':'paragraph','role':'company_filing','ordinal':1,'page':1,
           'text':'第二原始段','hints':{'source_id':'s'}}
    a={'source_id':'s','pdf_block':3,'block_sha256':token,'block_char_start':0,'block_char_end':5}
    b={'source_id':'s','pdf_block':3,'block_sha256':token,'block_char_start':6,'block_char_end':11}
    return left,right,a,b


@pytest.mark.parametrize('token',['local:block/乙-03','块零'])
def test_same_local_opaque_block_token_is_a_valid_source_edge(token):
    l,r,a,b=pair(token);before=deepcopy((l,r,a,b))
    proof=owner.source_member_neighbour(l,r,left_provenance=a,right_provenance=b)
    assert proof=={'left':'l','right':'r','basis':'native_block_character_ranges'}
    assert (l,r,a,b)==before


@pytest.mark.parametrize('fault',['different_token','empty_token','overlap','different_source'])
def test_opaque_identity_does_not_replace_real_member_proof(fault):
    l,r,a,b=pair('local:block/乙-03')
    if fault=='different_token': b['block_sha256']='local:block/甲-03'
    elif fault=='empty_token': a['block_sha256']=b['block_sha256']=''
    elif fault=='overlap': b['block_char_start']=4
    else: b['source_id']='other-source'
    assert owner.source_member_neighbour(l,r,left_provenance=a,right_provenance=b) is None
